param([Parameter(Mandatory=$true)][string]$SourcePath,[Parameter(Mandatory=$true)][string]$HeaderPath,[Parameter(Mandatory=$true)][string]$TestsCMakePath,[Parameter(Mandatory=$true)][string]$ForbiddenPaths)
$ErrorActionPreference='Stop';$s=Get-Content -Raw $SourcePath;$h=Get-Content -Raw $HeaderPath;$hn=(($h -replace '\r?\n\s*\*\s*',' ') -replace '\s+',' ');$tc=Get-Content -Raw $TestsCMakePath
function A([bool]$x,[string]$m){if(-not$x){throw $m}}
function B([string]$x,[string]$a,[string]$b){$i=$x.IndexOf($a);$j=$x.IndexOf($b,$i+$a.Length);A($i-ge 0-and$j-gt$i)"section $a";$x.Substring($i,$j-$i)}
function O([string]$x,[string[]]$v){$i=0;foreach($n in $v){$j=$x.IndexOf($n,$i,[StringComparison]::Ordinal);if($j-lt 0){return $false};$i=$j+$n.Length};$true}
function V([string]$x,[string]$y){foreach($n in @('RootLeaseVisitor','trusted synchronous visitor','OperationBusy','preserves visitor_status','return at PASSIVE','must not retain','must not reenter','separate from every runtime allocation','allocates nothing','serializer','VMX/EPT instruction','hook','IOCTL','public dispatch','VmxPersistentRuntimeVisitRootProofLease')){A($y.Contains($n))"header $n"};$e=B $x 'static bool RootLeaseExternalSeparate' 'static bool RootLeaseArgs';foreach($n in @('SIZE_MAX/sizeof(*s->Snapshot.Processors)','SIZE_MAX/sizeof(*x->Records)','s->Snapshot.Processors','x->Snapshot.Processors','x->Records','x->Contexts','x->Bindings','StoragePointers(s,p,z)','s->AllocationSizes[k]','Overlap(target,span)')){A($e.Contains($n))"external $n"};$a=B $x 'static bool RootLeaseArgs' 'static bool RootPhysical';foreach($n in @('visitor&&Span(r,sizeof(*r)','Span(i,sizeof(*i)','Span(context,context_bytes','Span(visitor_status,sizeof(*visitor_status)','!Overlap(a,b)','!Overlap(a,c)','!Overlap(a,d)','!Overlap(b,c)','!Overlap(b,d)','!Overlap(c,d)')){A($a.Contains($n))"args $n"};$q=B $x 'VMX_PERSISTENT_STATUS VmxPersistentRuntimeVisitRootProofLease' 'VMX_PERSISTENT_STATUS VmxPersistentRuntimeVisitVmcsBindings';A((O $q @('RootLeaseArgs(r,i,visitor,context,context_bytes,visitor_status)','KeGetCurrentIrql()!=PASSIVE_LEVEL','if(!RuntimeAcquire(r))','TeardownStage(r->Stage)','RuntimeValid(r)','RootLeaseExternalSeparate(r,context,context_bytes)','RootLeaseExternalSeparate(r,visitor_status','RootProofLocked(r,i,&proof)','visitor(context,&proof.Identity,&proof)','called=true','RtlSecureZeroMemory(&proof','RuntimeRelease(r)','if(called)*visitor_status=visited','return status')))'lease order';A((([regex]::Matches($q,'RuntimeRelease\(r\)')).Count-eq 1))'release once';A((([regex]::Matches($q,'visitor\(context')).Count-eq 1))'visitor once';A($q-notmatch '(?i)ExAllocate|ExFree|AllocatePool|FreePool|SerializerFactory|__vmx|Vmxon\s*\(|Vmxoff\s*\(|INVEPT|IOCTL|Hook')'lease forbidden'}
V $s $hn;A((([regex]::Matches($tc,'test_vmx_persistent_runtime_root_lease_contracts')).Count-eq 1))'test once';foreach($p in $ForbiddenPaths.Split(',')){A((Get-Content -Raw $p)-notmatch 'VmxPersistentRuntimeVisitRootProofLease')"unwired $p"}
$m=@($s.Replace('!Overlap(c,d);','true;'),$s.Replace('RootLeaseExternalSeparate(r,context,context_bytes)','true'),$s.Replace('RootLeaseExternalSeparate(r,visitor_status,sizeof(*visitor_status))','true'),$s.Replace('if(!RuntimeAcquire(r))','if(RuntimeAcquire(r))'),$s.Replace('TeardownStage(r->Stage)','false'),$s.Replace('else if(!RuntimeValid(r))status=VMX_PERSISTENT_STATUS_INVALID;','else if(false)status=VMX_PERSISTENT_STATUS_INVALID;'),$s.Replace('RootProofLocked(r,i,&proof)','VMX_PERSISTENT_STATUS_OK'),$s.Replace('visitor(context,&proof.Identity,&proof)','0'),$s.Replace('RtlSecureZeroMemory(&proof,sizeof(proof));',''),$s.Replace('RuntimeRelease(r);',''),$s.Replace('if(called)*visitor_status=visited;','*visitor_status=visited;'))
for($i=0;$i-lt$m.Count;$i++){A($m[$i]-ne$s)"mutation missing $i";$bad=$false;try{V $m[$i] $hn}catch{$bad=$true};A($bad)"accepted mutation $i"}
Write-Host 'PASS: synchronous runtime root-proof lease contracts'
